// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const BULK_UNITS = 100;
const BULK_FACTOR = 0.95;
const LARGE_ORDER_AMOUNT = 10000;
const NAME_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;

// Section order is the order in the report.
const REGIONS = [
  { code: 'DE', title: 'Germany', vatRate: 0.19 },
  { code: 'FR', title: 'France', vatRate: 0.2 },
  { code: 'UK', title: 'United Kingdom', vatRate: 0.2 },
];

const roundCents = (value) => Math.round(value * 100) / 100;

function groupThousands(digits, separator) {
  const groups = [];
  for (let end = digits.length; end > 0; end -= 3) {
    groups.unshift(digits.slice(Math.max(0, end - 3), end));
  }
  return groups.join(separator);
}

export function formatMoney(amount, region) {
  let sign = '';
  if (amount < 0) {
    sign = '-';
    amount = -amount;
  }
  const fixed = amount.toFixed(2);
  const integerPart = fixed.slice(0, fixed.length - 3);
  const cents = fixed.slice(-2);
  if (region === 'DE') {
    return sign + groupThousands(integerPart, '.') + ',' + cents + ' €';
  }
  if (region === 'FR') {
    return sign + groupThousands(integerPart, ' ') + ',' + cents + ' €';
  }
  if (region === 'UK') {
    return sign + '£' + groupThousands(integerPart, ',') + '.' + cents;
  }
  throw new Error('unknown region: ' + region);
}

function grossAmount(sale, vatRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) {
    net = net - (net * sale.discountPct) / 100;
  }
  if (sale.units >= BULK_UNITS) {
    net = net * BULK_FACTOR;
  }
  net = roundCents(net);
  const vat = roundCents(net * vatRate);
  return roundCents(net + vat);
}

function truncateName(name) {
  return name.length > NAME_WIDTH ? name.slice(0, NAME_WIDTH - 1) + '…' : name;
}

function formatLine(sale, amount, regionCode) {
  return (
    truncateName(sale.product).padEnd(NAME_WIDTH) +
    ' ' +
    String(sale.units).padStart(UNITS_WIDTH) +
    ' ' +
    formatMoney(amount, regionCode).padStart(MONEY_WIDTH)
  );
}

// Appends one region's section and returns its row and large-order counts.
function appendSection(lines, sales, { code, title, vatRate }) {
  const regionSales = sales.filter((s) => s.region === code && s.units > 0);
  if (regionSales.length === 0) {
    return { rows: 0, large: 0 };
  }
  lines.push('== ' + title + ' ==');
  let subtotal = 0;
  let large = 0;
  for (const sale of regionSales) {
    const amount = grossAmount(sale, vatRate);
    const isLarge = amount >= LARGE_ORDER_AMOUNT;
    lines.push(formatLine(sale, amount, code) + (isLarge ? ' *' : ''));
    if (isLarge) large++;
    subtotal += amount;
  }
  lines.push('Subtotal ' + code + ': ' + formatMoney(subtotal, code));
  lines.push('');
  return { rows: regionSales.length, large };
}

export function buildReport(sales, options) {
  options = options || {};
  if (options.format && options.format !== 'text') {
    throw new Error('unsupported format: ' + options.format);
  }
  if (options.month && !/^\d{4}-\d{2}$/.test(options.month)) {
    throw new Error('bad month: ' + options.month);
  }
  const lines = [options.month ? 'SALES REPORT ' + options.month : 'SALES REPORT', ''];
  let data = sales.slice();
  if (options.month) {
    data = data.filter((s) => s.date.slice(0, 7) === options.month);
  }
  data.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  let rows = 0;
  let large = 0;
  for (const region of REGIONS) {
    const section = appendSection(lines, data, region);
    rows += section.rows;
    large += section.large;
  }

  if (rows === 0) {
    lines.push('No sales.');
  } else {
    lines.push('Rows: ' + rows);
    lines.push('Large orders: ' + large);
  }
  return lines.join('\n') + '\n';
}
